import './App.scss';
import Header from './features/header/Header';
import {
  BrowserRouter, Route, Routes, useNavigate
} from 'react-router-dom';
import Game from './features/game/Game';
import GameList from './features/game-list/GameList';
import { Fragment, useEffect } from 'react';

function App() {
  const params = new URLSearchParams(window.location.search);
  const defaultGame = params.get('game');
  const navigate = useNavigate();
  useEffect(() => {
    if (defaultGame) {
      navigate(`/play/${defaultGame}`);
    }
  }, [defaultGame, navigate]);

  return (
    <div className="App">
      <Header></Header>
      <Routes>
        <Route path="/" element={<GameList></GameList>}></Route>
        <Route path="/play/:gameId" element={<Game></Game>}></Route>
      </Routes>
    </div>
  );
}

export default function AppWithRouter() {
  return (
    <BrowserRouter>
      <App />
    </BrowserRouter>
  );
}
